def find_seps(g):
    h,w=len(g),len(g[0])
    rows=[r for r in range(h) if g[r][0]!=0 and all(v==g[r][0] for v in g[r])]
    cols=[c for c in range(w) if g[0][c]!=0 and all(g[r][c]==g[0][c] for r in range(h))]
    return rows,cols

def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    rs,cs=find_seps(g)
    if not rs or not cs: return g
    th,tw=rs[0],cs[0]
    rstarts=[0]+[r+1 for r in rs]
    cstarts=[0]+[c+1 for c in cs]
    rstarts=[r for r in rstarts if r+th<=H]
    cstarts=[c for c in cstarts if c+tw<=W]
    nr,nc=len(rstarts),len(cstarts)
    panels=[[[g[rstarts[i]+y][cstarts[j]+x] for x in range(tw)] for y in range(th)] for i in range(nr) for j in range(nc)]
    # panel index helper
    def getpanel(i,j): return panels[i*nc+j]
    def reflected(coords, hf, vf):
        return frozenset((th-1-y if vf else y, tw-1-x if hf else x) for y,x in coords)
    colors=set(v for row in g for v in row if v!=0 and v not in {g[rs[0]][0],g[0][cs[0]]})
    # use tile contents only to collect meaningful colors (exclude divider values)
    colors=set(v for p in panels for row in p for v in row if v!=0)
    for i in range(nr-1):
      for j in range(nc-1):
       for color in colors:
        pats=[]
        for di,dj in [(0,0),(0,1),(1,0),(1,1)]:
          p=getpanel(i+di,j+dj)
          pts=frozenset((y,x) for y in range(th) for x in range(tw) if p[y][x]==color)
          if pts:
            canon=reflected(pts, hf=bool(dj), vf=bool(di))
            pats.append((di,dj,canon))
        if len(pats)>=3 and all(c==pats[0][2] for _,_,c in pats):
          base=pats[0][2]
          for di,dj in [(0,0),(0,1),(1,0),(1,1)]:
            p=getpanel(i+di,j+dj)
            if not any(p[y][x]==color for y in range(th) for x in range(tw)):
              add=reflected(base,hf=bool(dj),vf=bool(di))
              for y,x in add:
                rr,cc=rstarts[i+di]+y,cstarts[j+dj]+x
                if g[rr][cc]==0: g[rr][cc]=color
    return g

for name,inp,out in [('d1',d1i,d1o),('d2',d2i,d2o)]:
    pred=transform(inp)
    print(name, pred==out, sum(a!=b for ra,rb in zip(pred,out) for a,b in zip(ra,rb)))

