    row_starts = [r for r in [0] + [r + 1 for r in row_seps] if r + tile_h <= h]
    col_starts = [c for c in [0] + [c + 1 for c in col_seps] if c + tile_w <= w]
    nr, nc = len(row_starts), len(col_starts)
